import itertools
import json
import numpy as np

def fingerprint(rows):
    """Canonicalize hinge parameters algebraically; no input evaluation."""
    linear = np.zeros(rows.shape[1], dtype=np.int64)
    hinges = {}
    for sign, row in zip((1, 1, -1), rows):
        row = tuple(map(int, row))
        coefficients, bias = row[:-1], row[-1]
        lower = bias + sum(min(0, c) for c in coefficients)
        upper = bias + sum(max(0, c) for c in coefficients)
        if upper <= 0:
            continue
        if lower >= 0:
            linear += sign * np.asarray(row, dtype=np.int64)
        else:
            hinges[row] = hinges.get(row, 0) + sign
    return (
        tuple(map(int, linear)),
        tuple(sorted((r, c) for r, c in hinges.items() if c)),
    )

def decode(checkpoint):
    signals = [("input", i) for i in range(10)]

    for layer in range(4):
        matrix = np.asarray(W[f"{checkpoint}.w{layer}"])
        biases = np.asarray(W[f"{checkpoint}.b{layer}"])
        assert np.all(matrix == np.rint(matrix))
        assert np.all(biases == np.rint(biases))
        matrix = matrix.astype(np.int64)
        biases = biases.astype(np.int64)

        n = len(signals)
        zero = np.zeros(n + 1, dtype=np.int64)
        one = zero.copy()
        one[-1] = 1
        decoded = []

        for start in range(10, 34, 3):
            rows = np.zeros((3, n + 1), dtype=np.int64)
            rows[:, :10] = matrix[start:start + 3, :10]
            rows[:, -1] = biases[start:start + 3]

            if layer:
                for slot in range(8):
                    col = 10 + 3 * slot
                    block = matrix[start:start + 3, col:col + 3]
                    assert np.array_equal(block[:, 0], block[:, 1])
                    assert np.array_equal(block[:, 0], -block[:, 2])
                    rows[:, 10 + slot] = block[:, 0]

            wanted = fingerprint(rows)
            used = np.flatnonzero(np.any(rows[:, :-1] != 0, axis=0))
            atoms = []
            for index in used:
                vector = zero.copy()
                vector[index] = 1
                atoms.append((vector, signals[int(index)]))

            found = None

            def consider(parameters, expression):
                nonlocal found
                if found is None and fingerprint(np.stack(parameters)) == wanted:
                    found = expression

            consider((zero, zero, zero), ("constant", False))
            consider((one, zero, zero), ("constant", True))

            for a, ea in atoms:
                consider((a, zero, zero), ea)
                consider((one - a, zero, zero), ("not", ea))

            for (a, ea), (b, eb) in itertools.product(atoms, repeat=2):
                total = a + b
                consider((total - one, zero, zero), ("and", ea, eb))
                consider((total, zero, total - one), ("or", ea, eb))
                consider((total, zero, 2 * total - 2 * one), ("xor", ea, eb))
                consider((one, zero, total - one), ("nand", ea, eb))
                consider((one, total - one, total), ("nor", ea, eb))
                consider((a - b, b - a, zero), ("xor", ea, eb))

            if found is None:
                for (a, ea), (b, eb), (c, ec) in itertools.product(atoms, repeat=3):
                    total = a + b + c
                    consider(
                        (total - one, zero, total - 2 * one),
                        ("majority", ea, eb, ec),
                    )
                    consider(
                        (a + b - one, c - a, zero),
                        ("mux", ea, eb, ec),
                    )

            assert found is not None, (checkpoint, layer, start, rows)
            decoded.append(found)

        signals = [("input", i) for i in range(10)] + decoded

    expected_out = np.zeros((3, 34), dtype=np.float32)
    expected_out[0, 10:13] = (-1, -1, 1)
    expected_out[1, 10:13] = (1, 1, -1)
    assert np.array_equal(W[f"{checkpoint}.out"], expected_out)
    assert np.array_equal(W[f"{checkpoint}.bias"], [1, 0, -1])
    return signals[10]

def evaluate(expression, inputs):
    op = expression[0]
    if op == "input":
        return bool(inputs[expression[1]])
    if op == "constant":
        return expression[1]
    if op == "not":
        return not evaluate(expression[1], inputs)
    values = [evaluate(child, inputs) for child in expression[1:]]
    if op == "and":
        return values[0] and values[1]
    if op == "or":
        return values[0] or values[1]
    if op == "xor":
        return values[0] != values[1]
    if op == "nand":
        return not (values[0] and values[1])
    if op == "nor":
        return not (values[0] or values[1])
    if op == "majority":
        return sum(values) >= 2
    if op == "mux":
        return values[1] if values[0] else values[2]
    raise ValueError(op)

